import torch
import torch.nn as nn
import hashlib
from torch.utils.cpp_extension import load_inline

_STARK_EXTENSION = None

def _stark_strip_anchor_markers(source: str) -> str:
    cleaned_lines = []
    for line in source.splitlines():
        stripped = line.lstrip()
        if stripped.startswith('# <<<IMPROVE:') or stripped.startswith('# <<<END_IMPROVE>>>'):
            continue
        cleaned_lines.append(line)
    return '\n'.join(cleaned_lines)

def _stark_extension_name() -> str:
    digest = hashlib.sha1((_stark_strip_anchor_markers(CUDA_CPP_SRC) + _stark_strip_anchor_markers(CUDA_CU_SRC)).encode('utf-8')).hexdigest()[:12]
    return f'stark_cuda_l2_p43_{digest}'

def _stark_get_extension():
    global _STARK_EXTENSION
    if _STARK_EXTENSION is None:
        _STARK_EXTENSION = load_inline(
            name=_stark_extension_name(),
            cpp_sources=_stark_strip_anchor_markers(CUDA_CPP_SRC),
            cuda_sources=_stark_strip_anchor_markers(CUDA_CU_SRC),
            functions=None,
            extra_cflags=['-O3'],
            extra_cuda_cflags=['-O3', '--use_fast_math'],
            with_cuda=True,
            verbose=False,
        )
    return _STARK_EXTENSION

# <<<IMPROVE:user_helpers>>>
# <<<END_IMPROVE>>>

CUDA_CPP_SRC = r"""
# <<<IMPROVE:cuda_cpp>>>
#include <torch/extension.h>

torch::Tensor conv3d_maxpool_logsumexp_relu_cuda(torch::Tensor x);

torch::Tensor conv3d_maxpool_logsumexp_relu(torch::Tensor x) {
    TORCH_CHECK(x.is_cuda(), "Input must be a CUDA tensor");
    TORCH_CHECK(x.dtype() == torch::kFloat32, "Input must be float32");
    TORCH_CHECK(x.dim() == 5, "Input must be 5D (NCDHW)");
    return conv3d_maxpool_logsumexp_relu_cuda(x);
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("conv3d_maxpool_logsumexp_relu", &conv3d_maxpool_logsumexp_relu, "Fused maxpool+logsumexp+relu (CUDA)");
}
# <<<END_IMPROVE>>>
"""

CUDA_CU_SRC = r"""
# <<<IMPROVE:cuda_cu>>>
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <cmath>

__global__ void fused_maxpool_logsumexp_relu_kernel(
    const float* __restrict__ input,
    float* __restrict__ output,
    int N, int C, int D, int H, int W,
    int out_D, int out_H, int out_W
) {
    const int idx = blockIdx.x;
    const int n = idx / (out_D * out_H * out_W);
    const int spatial_idx = idx % (out_D * out_H * out_W);
    const int od = spatial_idx / (out_H * out_W);
    const int temp = spatial_idx % (out_H * out_W);
    const int oh = temp / out_W;
    const int ow = temp % out_W;

    if (n >= N) return;

    const int tid = threadIdx.x;
    const int id_base = od * 2;
    const int ih_base = oh * 2;
    const int iw_base = ow * 2;

    extern __shared__ float shared_mem[];
    float* channel_max = shared_mem;
    float* channel_sum = &shared_mem[C];

    float thread_pool_val = -INFINITY;
    if (tid < C) {
        float pool_max = -INFINITY;
        for (int kd = 0; kd < 2; ++kd) {
            int id = id_base + kd;
            if (id >= D) continue;
            for (int kh = 0; kh < 2; ++kh) {
                int ih = ih_base + kh;
                if (ih >= H) continue;
                for (int kw = 0; kw < 2; ++kw) {
                    int iw = iw_base + kw;
                    if (iw >= W) continue;
                    int input_idx = ((n * C + tid) * D + id) * H * W + ih * W + iw;
                    float val = input[input_idx];
                    pool_max = fmaxf(pool_max, val);
                }
            }
        }
        thread_pool_val = pool_max;
        channel_max[tid] = pool_max;
    } else {
        channel_max[tid] = -INFINITY;
    }
    __syncthreads();

    for (int stride = C / 2; stride > 0; stride >>= 1) {
        if (tid < stride && tid + stride < C) {
            channel_max[tid] = fmaxf(channel_max[tid], channel_max[tid + stride]);
        }
        __syncthreads();
    }

    float global_max = channel_max[0];
    __syncthreads();

    if (tid < C) {
        float exp_val = expf(thread_pool_val - global_max);
        channel_sum[tid] = exp_val;
    } else {
        channel_sum[tid] = 0.0f;
    }
    __syncthreads();

    for (int stride = C / 2; stride > 0; stride >>= 1) {
        if (tid < stride && tid + stride < C) {
            channel_sum[tid] += channel_sum[tid + stride];
        }
        __syncthreads();
    }

    if (tid == 0) {
        float sum_exp = channel_sum[0];
        float logsumexp_val = global_max + logf(sum_exp);
        float result = fmaxf(0.0f, logsumexp_val);
        int output_idx = ((n * 1 + 0) * out_D + od) * out_H * out_W + oh * out_W + ow;
        output[output_idx] = result;
    }
}

torch::Tensor conv3d_maxpool_logsumexp_relu_cuda(torch::Tensor x) {
    x = x.contiguous();
    const int N = x.size(0);
    const int C = x.size(1);
    const int D = x.size(2);
    const int H = x.size(3);
    const int W = x.size(4);

    const int out_D = (D + 1) / 2;
    const int out_H = (H + 1) / 2;
    const int out_W = (W + 1) / 2;

    auto output = torch::empty({N, 1, out_D, out_H, out_W}, x.options());

    const int total_output_voxels = N * out_D * out_H * out_W;
    const int threads = (C < 64) ? 64 : ((C < 128) ? 128 : 256);
    const int shared_mem_size = threads * 2 * sizeof(float);

    fused_maxpool_logsumexp_relu_kernel<<<total_output_voxels, threads, shared_mem_size>>>(
        x.data_ptr<float>(),
        output.data_ptr<float>(),
        N, C, D, H, W,
        out_D, out_H, out_W
    );

    return output;
}
# <<<END_IMPROVE>>>
"""

class ModelNew(nn.Module):
    """
        Model that performs a 3D convolution, max pooling, log sum exp, and ReLU activation.
        """
    def __init__(self, in_channels, out_channels, kernel_size, stride, padding):
        super().__init__()
        # <<<IMPROVE:init_body>>>
        self.conv = nn.Conv3d(in_channels, out_channels, kernel_size, stride=stride, padding=padding)
        self.max_pool = nn.MaxPool3d(kernel_size=2, stride=2)
        # <<<END_IMPROVE>>>

    def forward(self, x):
        # <<<IMPROVE:forward_stmt_1>>>
        # Baseline fallback keeps the official PyTorch forward path.
        # After implementing CUDA_CPP_SRC / CUDA_CU_SRC, call _stark_get_extension().your_entrypoint(...).
        """
                Args:
                    x: Input tensor of shape (batch_size, in_channels, depth, height, width)
                Returns:
                    Output tensor of shape (batch_size, out_channels, depth', height', width')
                """
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_2>>>
        x = self.conv(x)
        if x.is_cuda and x.dtype == torch.float32 and x.dim() == 5:
            return _stark_get_extension().conv3d_maxpool_logsumexp_relu(x.contiguous())
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_3>>>
        x = self.max_pool(x)
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_4>>>
        x = torch.logsumexp(x, dim=1, keepdim=True)
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_5>>>
        x = torch.relu(x)
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_6>>>
